export type ConfigAffectedRecords = z.infer<typeof configAffectedRecords>;
// zod mirrors of the P5 slice A source coverage and the S12-018 revision proposals (docs/api/openapi.yaml tag `studio`:
// getSourceCoverage, runSourceCoverageCheck, listRevisionProposals; ADR-0039 §6, §8, §12; REQ-S02-001, REQ-S12-018;
// p5-work-split §A.3; T-DG5-BE-B2). The OpenAPI file is the source of truth; the contract test parses every success
// body with these. runSourceCoverageCheck answers with the `configCheckRun` mirror of studio-checks.ts.
// A coverage run or a revision proposal tests and routes configuration; neither grants or records a business approval.

// ------------------------------------------------------------------------------------------------ source coverage

/** The ten counted source element sets of REQ-S02-001 (M0083), in the order of the report (ADR-0039 §6). */
export const SOURCE_SET_CODES = [
  "mode",
  "phase",
  "gate",
  "template",
  "tom_dimension",
  "forum",
  "benefit_lifecycle_step",
  "launch_window",
  "roaming_example",
  "health_question",
] as const;
export type SourceSetCode = (typeof SOURCE_SET_CODES)[number];
export const sourceSetCode = z.enum(SOURCE_SET_CODES);

const coverageResult = z.enum(["pass", "warn", "fail"]);
const sha256 = z.string().regex(/^[0-9a-f]{64}$/);

/** One element set of the report (`SourceCoverageSet`). Counts are integers, never decimals (ADR-0039 §12). */
export const sourceCoverageSet = z.strictObject({
  setCode: sourceSetCode,
  expected: z.number().int().min(0),
  present: z.number().int().min(0),
  removed: z.array(z.string()),
  plannedFeatures: z.array(z.string()),
  result: coverageResult,
});
export type SourceCoverageSet = z.infer<typeof sourceCoverageSet>;

/** getSourceCoverage (`SourceCoverageReport`). */
export const sourceCoverageReport = z.strictObject({
  versionId: uuid,
  contentSha256: sha256,
  result: coverageResult,
  sets: z.array(sourceCoverageSet),
});
export type SourceCoverageReport = z.infer<typeof sourceCoverageReport>;

/** getSourceCoverage query (`ConfigVersionIdQuery`): default, the newest published methodology version. */
export const sourceCoverageQuery = z.strictObject({ versionId: uuid.optional() });

/** runSourceCoverageCheck body (`SourceCoverageRunRequest`). */
export const sourceCoverageRunRequest = z.strictObject({ versionId: uuid });
export type SourceCoverageRunRequest = z.infer<typeof sourceCoverageRunRequest>;

// ------------------------------------------------------------------------------------------------ revision proposals

export const REVISION_SUBJECT_TYPES = ["methodology_version", "benefit_formula_version"] as const;
export type RevisionSubjectType = (typeof REVISION_SUBJECT_TYPES)[number];
export const revisionSubjectType = z.enum(REVISION_SUBJECT_TYPES);

/** One S12-018 record (`RevisionProposal`): validation, impact and review routing of a proposed revision. */
export const revisionProposal = z.strictObject({
  id: uuid,
  transformationId: uuid.nullable(),
  subjectType: revisionSubjectType,
  subjectId: uuid,
  subjectVersion: z.number().int().min(1),
  contentSha256: sha256,
  validationResult: z.enum(["pass", "fail"]),
  validationReport: z.record(z.string(), z.unknown()),
  impact: z.record(z.string(), z.unknown()),
  reviewerRoleCode: z.string(),
  reviewTaskCount: z.number().int().min(0),
  createdAt: timestamp,
});
export type RevisionProposal = z.infer<typeof revisionProposal>;
export const revisionProposalPage = page(revisionProposal);

/** listRevisionProposals filters (`RevisionSubjectTypeQuery`, `RevisionSubjectIdQuery`). */
export const revisionProposalListQuery = z.strictObject({
  subjectType: revisionSubjectType.optional(),
  subjectId: uuid.optional(),
});
// zod mirrors of the P5 slice A review, publish, rollback and review-policy operations (docs/api/openapi.yaml tag
// `studio`: submitConfigReview, listConfigReviews, decideConfigReview, withdrawConfigReview, publishConfigVersion,
// rollbackConfigVersion, listConfigReviewPolicies, updateConfigReviewPolicy; ADR-0039 §5, §7, §9, §13; REQ-S06-007,
// REQ-S06-009, REQ-S06-010; p5-work-split §A.4; T-DG5-BE-B3). The OpenAPI file is the source of truth; the contract
// test parses every success body with these. publishConfigVersion and rollbackConfigVersion answer with the
// `configVersion` mirror of studio.ts.
// A configuration review is not a business approval: approving a Studio change grants and records no G1-G6 decision.

const sha256 = z.string().regex(/^[0-9a-f]{64}$/);

// ------------------------------------------------------------------------------------------------ review requests

export const CONFIG_REVIEW_STATUSES = ["pending", "approved", "changes_requested", "withdrawn"] as const;
export type ConfigReviewStatus = (typeof CONFIG_REVIEW_STATUSES)[number];

/** submitConfigReview body (`ConfigReviewSubmit`). */
export const configReviewSubmit = z.strictObject({ note: freeText(1, 4000).optional() });
export type ConfigReviewSubmit = z.infer<typeof configReviewSubmit>;

/** The configured review of exactly one content hash (`ConfigReviewRequest`). */
export const configReviewRequest = z.strictObject({
  id: uuid,
  versionId: uuid,
  contentSha256: sha256,
  reviewerRoleCode: z.string(),
  status: z.enum(CONFIG_REVIEW_STATUSES),
  requestNote: z.string().min(1).max(4000).nullable(),
  revisionProposalId: uuid.nullable(),
  requestedBy: uuid,
  requestedAt: timestamp,
  decidedBy: uuid.nullable(),
  decidedAt: timestamp.nullable(),
  decisionNote: z.string().min(1).max(4000).nullable(),
  version: z.number().int().min(1),
  createdAt: timestamp,
  updatedAt: timestamp,
});
export type ConfigReviewRequest = z.infer<typeof configReviewRequest>;
export const configReviewRequestPage = page(configReviewRequest);

/**
 * decideConfigReview body (`ConfigReviewDecision`). The note is required when changes are requested; the API answers
 * 400 `validation.required` at `/note` when it is missing (the 0062 CHECK `config_review_request_changes_noted`).
 */
export const configReviewDecision = z.strictObject({
  outcome: z.enum(["approve", "request_changes"]),
  note: freeText(1, 4000).optional(),
});
export type ConfigReviewDecision = z.infer<typeof configReviewDecision>;

// ------------------------------------------------------------------------------------------------ rollback

/** rollbackConfigVersion body (`ConfigRollbackRequest`): the reason is the rollback draft's change summary. */
export const configRollbackRequest = z.strictObject({ reason: freeText(3, 4000) });
export type ConfigRollbackRequest = z.infer<typeof configRollbackRequest>;

// ------------------------------------------------------------------------------------------------ review policies

/** The policy rows: the six configuration kinds and the S12-018 `benefit_formula` routing row (`ConfigKindPath`). */
export const CONFIG_REVIEW_POLICY_KINDS = [
  "methodology",
  "scoring_defaults",
  "form_schema",
  "procedure",
  "automation_rule_set",
  "health_check_scheme",
  "benefit_formula",
] as const;
export type ConfigReviewPolicyKind = (typeof CONFIG_REVIEW_POLICY_KINDS)[number];
export const configReviewPolicyKind = z.enum(CONFIG_REVIEW_POLICY_KINDS);

/** One kind's review requirement and reviewer role (`ConfigReviewPolicy`). */
export const configReviewPolicy = z.strictObject({
  configKind: z.string(),
  reviewRequired: z.boolean(),
  reviewerRoleCode: z.string(),
  version: z.number().int().min(1),
  updatedAt: timestamp,
  updatedBy: uuid.nullable(),
});
export type ConfigReviewPolicy = z.infer<typeof configReviewPolicy>;
export const configReviewPolicyList = z.strictObject({ items: z.array(configReviewPolicy) });

/** updateConfigReviewPolicy body (`ConfigReviewPolicyUpdate`): at least one member. */
export const configReviewPolicyUpdate = z
  .strictObject({
    reviewRequired: z.boolean().optional(),
    reviewerRoleCode: z
      .string()
      .regex(/^[A-Z_]{2,32}$/)
      .optional(),
  })
  .refine((v) => v.reviewRequired !== undefined || v.reviewerRoleCode !== undefined, "validation.empty_update");
export type ConfigReviewPolicyUpdate = z.infer<typeof configReviewPolicyUpdate>;

