// Shared UI kit of the P4 slice I and C screens (T-DG4-FE-A): the one form dialog every action uses, the form-level
// alert, person names, due dates (Unknown with its reason, never a guessed date) and the business-approval note.
//  - S-7: one form-level alert per form (role="alert"); field errors sit on their fields; actions are session-bound
//    (beginSessionGuard); the label is "business approval", never an engineering gate.
//  - Every versioned change sends If-Match with the record version the user saw; a 409 says nothing was saved and
//    reloads the data (the caller's onDone), a 428 is translated like any problem.
//  - Problem codes are translated at render time from `problems.*` (and the page namespace's `<ns>.problem.*` first).
import { useQueries } from "@tanstack/react-query";
import type { TFunction } from "i18next";
import { useId, useRef, useState, type ReactNode } from "react";
import { useTranslation } from "react-i18next";
import { hasText } from "@mth/shared/schemas";
import { ApiError, api } from "../../api/client.ts";
import { keys, shouldRetry } from "../../api/queries.ts";
import type { User } from "../../api/types.ts";
import { useLocale } from "../../app/locale.ts";
import { useMe } from "../../auth/session.tsx";
import { beginSessionGuard } from "../../auth/sessionBound.ts";
import { BLANK_CODE, Dialog, Field, REQUIRED_CODE, useFocusFirstInvalid } from "../../components/Form.tsx";
import { Icon } from "../../components/Icon.tsx";
import { formatBusinessDate } from "../../lib/format.ts";
import { apiProblemText, errorMessage, fieldErrorMessage, pointerToField } from "../../lib/problem.ts";

// ------------------------------------------------------------------------------------------------ problems

const codeKey = (code: string) => code.replace(/\./g, "__");

/** The translated message of an error: the page namespaces' own `problem.*` texts first, then `problems.*`. */
export function p4ProblemMessage(t: TFunction, error: unknown, namespaces: readonly string[] = []): string {
  if (error instanceof ApiError && error.code) {
    const codes = [error.code, ...error.fieldErrors.map((fe) => fe.code)];
    for (const code of codes)
      for (const ns of namespaces) {
        const own = t(`${ns}.problem.${codeKey(code)}`, { defaultValue: "" });
        if (own) return own;
      }
    const shared = apiProblemText(t, error);
    if (shared) return shared;
  }
  return errorMessage(t, error);
}

/** The form's one alert (S-7). A 409 adds "nothing was saved; the latest data has been loaded". */
export function FormAlert({
  error,
  namespaces = [],
  extra,
}: {
  error: unknown;
  namespaces?: readonly string[];
  extra?: ReactNode;
}) {
  const { t } = useTranslation();
  if (!error) return null;
  const conflict = error instanceof ApiError && error.status === 409;
  // A stale business approval is not a "reload and retry" case: the record itself changed (the caller links to it).
  const reloaded = conflict && error.code !== "approval.stale_version";
  return (
    <div
      className="banner banner--error"
      role="alert"
      data-state={conflict ? "conflict" : "error"}
      data-problem={error instanceof ApiError ? (error.code ?? "") : ""}
    >
      <p>
        <Icon name="alert" /> {p4ProblemMessage(t, error, namespaces)}
      </p>
      {reloaded ? <p className="small">{t("myWork.ui.conflictReloaded")}</p> : null}
      {extra}
    </div>
  );
}

// ------------------------------------------------------------------------------------------------ the form dialog


/**
 * Display names of people by id: the signed-in user from the session, others from GET /users/{id} where the caller
 * may read users. Someone the caller cannot read is "Person ·abcd" (a short, non-identifying suffix), never blank.
 */
export function useUserNames(ids: readonly (string | null | undefined)[]): (id: string | null | undefined) => string {
  const { t } = useTranslation();
  const me = useMe();
  const unique = [...new Set(ids.filter((x): x is string => typeof x === "string" && x !== me.user.id))];
  const users = useQueries({
    queries: unique.map((id) => ({
      queryKey: keys.user(id),
      queryFn: () => api.get<User>(`/api/v1/users/${id}`),
      retry: shouldRetry,
      staleTime: 60_000,
    })),
  });
  const names = new Map<string, string>([[me.user.id, me.user.displayName]]);
  users.forEach((q, i) => {
    if (q.data) names.set(unique[i]!, q.data.displayName);
  });
  return (id) => {
    if (!id) return t("common.value.notAssigned");
    const n = names.get(id);
    if (n) return id === me.user.id ? `${n} · ${t("common.people.me")}` : n;
    return t("myWork.ui.person", { ref: id.slice(-4) });
  };
}

// ------------------------------------------------------------------------------------------------ dates and notes

/** A business date, or Unknown with its reason (never a guessed date, never "on time"). */
export function DueDate({ date, reason }: { date: string | null | undefined; reason?: string | null | undefined }) {
  const { t } = useTranslation();
  const locale = useLocale();
  const formatted = formatBusinessDate(date ?? null, locale);
  if (formatted) return <span data-due={date}>{formatted}</span>;
  return (
    <span className="status-chip status-chip--unknown status-chip--wrap" data-due="unknown">
      <Icon name="question" />{" "}
      <span>
        {t("common.value.unknown")}
        {reason
          ? ` (${t(`myWork.ui.unknownReason.${reason}`, { defaultValue: t("myWork.ui.unknownReason.other") })})`
          : ""}
      </span>
    </span>
  );
}

/** "Business approval" note (S-7): an in-product business decision, never an engineering delivery gate. */
export function BusinessApprovalNote({ body }: { body: string }) {
  const { t } = useTranslation();
  return (
    <p className="banner banner--info" role="note" data-state="business-approval">
      <Icon name="lock" /> <strong>{t("myWork.ui.businessApproval")}</strong>: {body}
    </p>
  );
}

/** The read-only note of a screen the caller can see but not change (AUD and other read-only roles; S-7). */
export function ReadOnlyNote({ body }: { body?: string }) {
  const { t } = useTranslation();
  return (
    <p className="banner banner--info" role="note" data-state="read-only">
      <Icon name="lock" /> {body ?? t("myWork.ui.readOnly")}
    </p>
  );
}

/** "YYYY-MM-DDTHH:mm" (a datetime-local value) -> ISO UTC, read in the given IANA zone; null when invalid. */
export { zonedLocalToUtcIso } from "../../lib/format.ts";
// Client-side register table for the P2 registers (REQ-S15-013): a whole register of one transformation is loaded
// (bounded), then sorted, filtered, paginated and column-selected here. Sorting is announced with aria-sort, the
// filter is a labelled search box, column selection is persisted per table and pagination is a labelled navigation.
// Missing values sort last and render as Unknown/None, never as 0.
import { useId, useMemo, useState, type ReactNode } from "react";
import { useTranslation } from "react-i18next";
import { ColumnPicker, usePersistentVisibility } from "./DataTable.tsx";
import { Icon } from "./Icon.tsx";
import { EmptyState } from "./States.tsx";

export interface RegisterColumn<T> {
  readonly id: string;
  readonly header: string;
  readonly cell: (row: T) => ReactNode;
  /** Value used for sorting; null/undefined sorts last. Columns without it are not sortable. */
  readonly sortValue?: (row: T) => string | number | null | undefined;
  /** Text searched by the filter box (defaults to the sort value). */
  readonly filterText?: (row: T) => string | null | undefined;
  /** Columns that carry the row's identity or actions cannot be hidden. */
  readonly hideable?: boolean;
  /** Rendered as the row header (<th scope="row">). */
  readonly rowHeader?: boolean;
}

type SortDir = "asc" | "desc";

export function RegisterTable<T>({
  id,
  caption,
  rows,
  columns,
  getRowId,
  emptyTitle,
  emptyBody,
  toolbar,
  defaultSort,
  pageSize: initialPageSize = 10,
}: {
  /** Stable id used to persist the column selection. */
  id: string;
  caption: string;
  rows: readonly T[];
  columns: readonly RegisterColumn<T>[];
  getRowId: (row: T) => string;
  emptyTitle: string;
  emptyBody?: string;
  toolbar?: ReactNode;
  defaultSort?: { id: string; dir: SortDir };
  pageSize?: number;
}) {
  const { t, i18n } = useTranslation();
  const filterId = useId();
  const [visibility, setVisibility] = usePersistentVisibility(`p2.${id}`);
  const [sort, setSort] = useState<{ id: string; dir: SortDir } | null>(defaultSort ?? null);
  const [filter, setFilter] = useState("");
  const [page, setPage] = useState(0);
  const [pageSize, setPageSize] = useState(initialPageSize);

  const visible = columns.filter((c) => visibility[c.id] !== false || c.hideable === false);

// Mandatory-reason confirmation (archive, revoke, remove): the reason is validated with the shared `reason` schema
// (3–1000 characters, trimmed by the server) before the request, and server errors are shown translated inside the
// dialog. The blank-text rule of every P2 form applies (F-DG2-210, BE7): a non-empty reason with no visible content
// (spaces or invisible characters such as U+200F only) is an inline `validation.blank` error and nothing is sent; a
// server 400 on `/reason` lands on the field, never as a generic failure. The text is sent as typed.
import { reasonRequest } from "@mth/shared/schemas";
import { useRef, useState } from "react";
import { useTranslation } from "react-i18next";
import { ApiError } from "../api/client.ts";
import { beginSessionGuard } from "../auth/sessionBound.ts";
import { errorMessage, fieldErrorMessage } from "../lib/problem.ts";
import { BLANK_CODE, Dialog, Field, isBlankText, issueCode, useFocusFirstInvalid } from "./Form.tsx";

export function ReasonDialog({
  title,
  description,
  confirmLabel,
  onConfirm,
  onClose,
}: {
  title: string;
  description: string;
  confirmLabel: string;
  onConfirm: (reason: string) => Promise<void>;
  onClose: () => void;
}) {
  const { t } = useTranslation();
  const [reason, setReason] = useState("");
  /** FE12: the field-error code; translated at render time so a visible message follows a language switch. */
  const [fieldErrorCode, setFieldErrorCode] = useState<string | undefined>();
  const fieldError = fieldErrorCode === undefined ? undefined : fieldErrorMessage(t, fieldErrorCode);
  const [serverError, setServerError] = useState<unknown>(null);
  const [busy, setBusy] = useState(false);
  const dialogRef = useRef<HTMLDivElement>(null);
  const focusInvalid = useFocusFirstInvalid(dialogRef);

  const showFieldError = (code: string) => {
    setFieldErrorCode(code);
    focusInvalid();
  };
    </div>
  );
}

export interface ConflictRow {
  readonly field: string;
  readonly label: string;
  readonly mine: string;
  readonly current: string;
}

/**
 * 409 version conflict (A14): nothing was saved. Shows the user's unsaved values next to the latest saved values and
 * offers to re-apply the change on top of the latest version or to discard it.
 */
export function ConflictPanel({
  yourVersion,
  currentVersion,
  rows,
  onReapply,
  onDiscard,
  busy,
}: {
  yourVersion: number;
  currentVersion: number | null;
  rows: readonly ConflictRow[];
  onReapply?: () => void;
  onDiscard: () => void;
  busy?: boolean;
}) {
  const { t } = useTranslation();
  return (
    <section
      className="banner banner--warning conflict"
      role="alert"
      aria-labelledby="conflict-title"
      data-state="conflict"
    >
      <h2 id="conflict-title" className="conflict__title">
        <Icon name="alert" /> {t("common.conflict.title")}
      </h2>
      <p>
        {t("common.conflict.body", {
          yours: yourVersion,
          current: currentVersion ?? t("common.value.unknown"),
        })}
      </p>
      {rows.length > 0 ? (
        <table className="table table--compact">
          <caption>{t("common.conflict.compareCaption")}</caption>
          <thead>
            <tr>
              <th scope="col">{t("common.conflict.field")}</th>
              <th scope="col">{t("common.conflict.mine")}</th>
              <th scope="col">{t("common.conflict.current")}</th>
            </tr>
          </thead>
          <tbody>
            {rows.map((r) => (
              <tr key={r.field}>
                <th scope="row">{r.label}</th>
                <td>{r.mine}</td>
                <td>{r.current}</td>
              </tr>
            ))}
          </tbody>
        </table>
      ) : null}
      <div className="form__actions">
        {onReapply ? (
          <button type="button" className="button button--primary" onClick={onReapply} disabled={busy}>
            {t("common.conflict.reapply")}
          </button>
        ) : null}
        <button type="button" className="button button--secondary" onClick={onDiscard} disabled={busy}>
          {t("common.conflict.discard")}
        </button>
      </div>
    </section>
  );
}

/**
 * Renders a query's state explicitly: loading, no-permission (403/404), error (no data), stale (data shown, refresh
 * failed), empty, or the content.
 */
export function QueryState<T>({
  query,
  isEmpty,
  empty,
  children,
}: {
  query: UseQueryResult<T, unknown>;
  isEmpty?: (data: T) => boolean;
  empty?: ReactNode;
  children: (data: T) => ReactNode;
}) {
  // F-DG2-530: the query's answer belonged to a previous session. It is not an error of this one: it is loaded again
  // under the current session (once per such failure, so bounded), and shown as loading meanwhile.
  const sessionChanged = query.isError && isSessionChangedError(query.error);
  const { refetch, errorUpdatedAt } = query;
  useEffect(() => {
    if (sessionChanged) void refetch();
  }, [sessionChanged, errorUpdatedAt, refetch]);
